1	//
2	//  AppPreferences.swift
3	//  SwiftMandarin
4	//
5	//  App-wide, cross-cutting user preferences that make the app bilingual:
6	//  - LearnerMode flips the app between English-centric and Mandarin-centric.
7	//  - PhotoScanLanguage controls OCR recognition language (fixes the
8	//    "stuck on English / can't read Mandarin" photo bug).
9	//  - dualNarration enables speaking both the word and its translation.
10	//
11	
12	import Foundation
13	import SwiftUI
14	
15	// MARK: - Learner Mode
16	
17	/// Who the app is centered on. Drives default translation direction,
18	/// default OCR scan language, and which language is emphasized in narration.
19	enum LearnerMode: String, CaseIterable, Identifiable, Codable {
20	    /// English speaker learning Mandarin (the original app audience).
21	    case englishToMandarin
22	    /// Mandarin speaker learning English.
23	    case mandarinToEnglish
24	    /// Learning both languages at once.
25	    case bilingual
26	
27	    var id: String { rawValue }
28	
29	    /// Short label shown in the user's own language emphasis.
30	    var displayName: String {
31	        switch self {
32	        case .englishToMandarin: return "English speaker learning 中文"
33	        case .mandarinToEnglish: return "中文母语者学英语"
34	        case .bilingual: return "Bilingual · 双语学习"
35	        }
36	    }
37	
38	    var shortLabel: String {
39	        switch self {
40	        case .englishToMandarin: return "EN → 中"
41	        case .mandarinToEnglish: return "中 → EN"
42	        case .bilingual: return "EN ⇄ 中"
43	        }
44	    }
45	
46	    var iconName: String {
47	        switch self {
48	        case .englishToMandarin: return "character.book.closed"
49	        case .mandarinToEnglish: return "a.book.closed"
50	        case .bilingual: return "arrow.left.arrow.right.circle"
51	        }
52	    }
53	
54	    var detail: String {
55	        switch self {
56	        case .englishToMandarin:
57	            return "Interface and defaults favor translating into Chinese; narration leads with Mandarin."
58	        case .mandarinToEnglish:
59	            return "界面与默认方向偏向译成英文；朗读以英文为主。"
60	        case .bilingual:
61	            return "Balanced defaults for studying both languages; both narrations are always offered."
62	        }
63	    }
64	
65	    /// The default translation direction this mode implies.
66	    var defaultDirection: TranslationDirection {
67	        switch self {
68	        case .englishToMandarin, .bilingual: return .englishToChinese
69	        case .mandarinToEnglish: return .chineseToEnglish
70	        }
71	    }
72	
73	    /// Whether this mode treats Mandarin as the language the user is learning
74	    /// (so explanations/definitions should be richer in Mandarin) vs. English.
75	    var learningLanguageIsChinese: Bool {
76	        switch self {
77	        case .englishToMandarin: return true
78	        case .mandarinToEnglish: return false
79	        case .bilingual: return true
80	        }
81	    }
82	}
83	
84	// MARK: - Photo Scan Language
85	
86	/// Controls the OCR recognition language for the photo / camera / screenshot
87	/// pipeline. This is the user-facing fix for "cannot switch languages".
88	enum PhotoScanLanguage: String, CaseIterable, Identifiable, Codable {
89	    case auto
90	    case chinese
91	    case english
92	    case bilingual
93	
94	    var id: String { rawValue }
95	
96	    var displayName: String {
97	        switch self {
98	        case .auto: return "自动 · Auto"
99	        case .chinese: return "中文"
100	        case .english: return "English"
101	        case .bilingual: return "双语 · Both"
102	        }
103	    }
104	
105	    var iconName: String {
106	        switch self {
107	        case .auto: return "wand.and.stars"
108	        case .chinese: return "character.textbox"
109	        case .english: return "textformat.abc"
110	        case .bilingual: return "globe.asia.australia"
111	        }
112	    }
113	
114	    /// Vision `recognitionLanguages`, ordered by priority. Chinese is listed
115	    /// first in mixed modes so Chinese glyphs are never mangled into Latin.
116	    var recognitionLanguages: [String] {
117	        switch self {
118	        case .auto, .bilingual: return ["zh-Hans", "zh-Hant", "en-US", "en-GB"]
119	        case .chinese: return ["zh-Hans", "zh-Hant"]
120	        case .english: return ["en-US", "en-GB"]
121	        }
122	    }
123	
124	    /// Language correction is an English-language model that corrupts Chinese
125	    /// OCR output, so it is disabled when recognizing Chinese only.
126	    var usesLanguageCorrection: Bool {
127	        switch self {
128	        case .chinese: return false
129	        case .auto, .english, .bilingual: return true
130	        }
131	    }
132	}
