134	// MARK: - App Preferences
135	
136	/// Observable, app-wide preferences singleton (persisted to UserDefaults).
137	@Observable
138	@MainActor
139	final class AppPreferences {
140	
141	    static let shared = AppPreferences()
142	
143	    private enum Keys {
144	        static let learnerMode = "learner_mode"
145	        static let photoScanLanguage = "photo_scan_language"
146	        static let dualNarration = "dual_narration"
147	        static let ttsRate = "tts_rate"
148	        static let aiAudioEnabled = "ai_audio_enabled"
149	        static let aiAudioRegion = "ai_audio_region"
150	        static let aiAudioModel = "ai_audio_model"
151	        static let aiAudioChineseVoice = "ai_audio_chinese_voice"
152	        static let aiAudioEnglishVoice = "ai_audio_english_voice"
153	        static let aiAudioChineseVoiceUsesCustomLanguage = "ai_audio_chinese_voice_custom_language"
154	        static let aiAudioEnglishVoiceUsesCustomLanguage = "ai_audio_english_voice_custom_language"
155	        static let aiAudioSpeed = "ai_audio_speed"
156	        static let aiAudioFallbackToSystemSpeech = "ai_audio_fallback_to_system_speech"
157	    }
158	
159	    /// The allowed text-to-speech rate range. 0.5 is
160	    /// `AVSpeechUtteranceDefaultSpeechRate`; below ~0.35 speech sounds broken
161	    /// and above 0.6 it is too fast to shadow.
162	    static let ttsRateRange: ClosedRange<Double> = 0.35...0.6
163	
164	    /// MiniMax accepts speech speeds from 0.5× through 2×.
165	    static let aiAudioSpeedRange: ClosedRange<Double> = 0.5...2.0
166	
167	    /// The app's learner-centric mode. Changing it updates the default
168	    /// translation direction used across the app.
169	    var learnerMode: LearnerMode {
170	        didSet {
171	            guard oldValue != learnerMode else { return }
172	            UserDefaults.standard.set(learnerMode.rawValue, forKey: Keys.learnerMode)
173	            // Adapt the shared default translation direction so all features follow.
174	            UserDefaults.standard.set(learnerMode.defaultDirection.rawValue, forKey: "defaultDirection")
175	            // Bidirectional sync: a single-direction mode also re-orients the
176	            // interface (= native) language, so the many views that key off
177	            // `LocalizationManager.learningIsChinese` actually follow the picker
178	            // instead of diverging from it. `.bilingual` keeps whatever
179	            // interface language is currently active (treated explicitly).
180	            // `LocalizationManager.language`'s own `didSet` is guarded against
181	            // no-op assignments, so this cannot loop.
182	            switch learnerMode {
183	            case .englishToMandarin:
184	                LocalizationManager.shared.language = .english
185	            case .mandarinToEnglish:
186	                LocalizationManager.shared.language = .chinese
187	            case .bilingual:
188	                break
189	            }
190	        }
191	    }
192	
193	    /// OCR recognition language preference for the photo pipeline.
194	    var photoScanLanguage: PhotoScanLanguage {
195	        didSet {
196	            UserDefaults.standard.set(photoScanLanguage.rawValue, forKey: Keys.photoScanLanguage)
197	        }
198	    }
199	
200	    /// When enabled, word-detail views offer narration in BOTH languages.
201	    var dualNarration: Bool {
202	        didSet {
203	            UserDefaults.standard.set(dualNarration, forKey: Keys.dualNarration)
204	        }
205	    }
206	
207	    /// Text-to-speech rate applied to every utterance (see `SpeechService`).
208	    /// Clamped to `ttsRateRange`; 0.5 matches the system default rate.
209	    var ttsRate: Double {
210	        didSet {
211	            let clamped = min(max(ttsRate, Self.ttsRateRange.lowerBound), Self.ttsRateRange.upperBound)
212	            if clamped != ttsRate {
213	                ttsRate = clamped  // re-enters didSet once with a valid value
214	                return
215	            }
216	            UserDefaults.standard.set(ttsRate, forKey: Keys.ttsRate)
217	        }
218	    }
219	
220	    /// Routes read-aloud actions through MiniMax when a Keychain credential is
221	    /// available. This is deliberately opt-in because it sends the spoken text
222	    /// to a network service and may incur API usage charges.
223	    var aiAudioEnabled: Bool {
224	        didSet { UserDefaults.standard.set(aiAudioEnabled, forKey: Keys.aiAudioEnabled) }
225	    }
226	
227	    /// Selects MiniMax's regional API host independently of the text-model
228	    /// provider configuration.
229	    var aiAudioRegion: MiniMaxAPIRegion {
230	        didSet {
231	            UserDefaults.standard.set(aiAudioRegion.rawValue, forKey: Keys.aiAudioRegion)
232	            guard oldValue != aiAudioRegion else { return }
233	            invalidateCredentialScopedVoiceProvenance()
234	        }
235	    }
236	
237	    /// T2A model identifier. Settings may expose this as editable so a newer
238	    /// compatible speech model can be adopted without an app release.
239	    var aiAudioModel: String {
240	        didSet {
241	            let trimmed = aiAudioModel.trimmingCharacters(in: .whitespacesAndNewlines)
242	            if trimmed != aiAudioModel {
243	                aiAudioModel = trimmed
244	                return
245	            }
246	            UserDefaults.standard.set(aiAudioModel, forKey: Keys.aiAudioModel)
247	        }
248	    }
249	
250	    var aiAudioChineseVoice: String {
251	        didSet {
252	            let trimmed = aiAudioChineseVoice.trimmingCharacters(in: .whitespacesAndNewlines)
253	            if trimmed != aiAudioChineseVoice {
254	                aiAudioChineseVoice = trimmed
255	                return
256	            }
257	            UserDefaults.standard.set(aiAudioChineseVoice, forKey: Keys.aiAudioChineseVoice)
258	        }
259	    }
260	
261	    var aiAudioEnglishVoice: String {
262	        didSet {
263	            let trimmed = aiAudioEnglishVoice.trimmingCharacters(in: .whitespacesAndNewlines)
264	            if trimmed != aiAudioEnglishVoice {
265	                aiAudioEnglishVoice = trimmed
266	                return
267	            }
268	            UserDefaults.standard.set(aiAudioEnglishVoice, forKey: Keys.aiAudioEnglishVoice)
269	        }
270	    }
271	
272	    /// Account-created/custom IDs can legally resemble public system IDs.
273	    /// Persisting the user's explicit slot assignment keeps validation stable
274	    /// across catalog refreshes and relaunches without guessing provenance.
275	    var aiAudioChineseVoiceUsesCustomLanguage: Bool {
276	        didSet {
277	            UserDefaults.standard.set(
278	                aiAudioChineseVoiceUsesCustomLanguage,
279	                forKey: Keys.aiAudioChineseVoiceUsesCustomLanguage
280	            )
281	        }
282	    }
283	
284	    var aiAudioEnglishVoiceUsesCustomLanguage: Bool {
285	        didSet {
286	            UserDefaults.standard.set(
287	                aiAudioEnglishVoiceUsesCustomLanguage,
288	                forKey: Keys.aiAudioEnglishVoiceUsesCustomLanguage
289	            )
290	        }
291	    }
292	
293	    var aiAudioSpeed: Double {
294	        didSet {
295	            let clamped = min(max(aiAudioSpeed, Self.aiAudioSpeedRange.lowerBound),
296	                              Self.aiAudioSpeedRange.upperBound)
297	            if clamped != aiAudioSpeed {
298	                aiAudioSpeed = clamped
299	                return
300	            }
301	            UserDefaults.standard.set(aiAudioSpeed, forKey: Keys.aiAudioSpeed)
302	        }
303	    }
304	
305	    /// Keeps read-aloud useful when the network, API key, or MiniMax service is
306	    /// unavailable. Users can disable this when they prefer failures to be
307	    /// explicit instead of switching voices.
308	    var aiAudioFallbackToSystemSpeech: Bool {
309	        didSet {
310	            UserDefaults.standard.set(aiAudioFallbackToSystemSpeech,
311	                                      forKey: Keys.aiAudioFallbackToSystemSpeech)
312	        }
313	    }
314	
315	    /// Account-created voices can use system-looking prefixes, but that proof
316	    /// belongs to the MiniMax account and regional catalog where it was
317	    /// observed. Crossing either boundary must fail closed until a live
318	    /// catalog confirms the selected ID is account-created again.
319	    func invalidateCredentialScopedVoiceProvenance() {
320	        aiAudioChineseVoiceUsesCustomLanguage =
321	            MiniMaxVoiceDescriptor.reconciledSlotLanguageAssignment(
322	                voiceID: aiAudioChineseVoice,
323	                persistedAssignment: aiAudioChineseVoiceUsesCustomLanguage,
324	                liveCatalogSource: nil,
325	                scopeChanged: true
326	            )
327	        aiAudioEnglishVoiceUsesCustomLanguage =
328	            MiniMaxVoiceDescriptor.reconciledSlotLanguageAssignment(
329	                voiceID: aiAudioEnglishVoice,
330	                persistedAssignment: aiAudioEnglishVoiceUsesCustomLanguage,
331	                liveCatalogSource: nil,
332	                scopeChanged: true
333	            )
334	    }
335	
336	    /// Align the learner mode with the interface language (the interface
337	    /// language is the user's native language, so the learning direction
338	    /// follows from it). Called by `LocalizationManager` whenever the in-app
339	    /// language toggle changes, so one gesture re-orients the whole app.
340	    func syncLearnerMode(toInterfaceLanguage language: AppLanguage) {
341	        // Preserve an explicit bilingual choice: toggling the interface language
342	        // must not silently collapse `.bilingual` into a single direction.
343	        guard learnerMode != .bilingual else { return }
344	        let target: LearnerMode = (language == .chinese) ? .mandarinToEnglish : .englishToMandarin
345	        if learnerMode != target {
346	            learnerMode = target
347	        }
348	    }
349	
350	    private init() {
351	        let savedMode = UserDefaults.standard.string(forKey: Keys.learnerMode)
352	        // First launch: derive the learning direction from the interface
353	        // language (中文 UI → native Mandarin speaker learning English).
354	        let derivedDefault: LearnerMode =
355	            LocalizationManager.shared.language == .chinese ? .mandarinToEnglish : .englishToMandarin
356	        self.learnerMode = savedMode.flatMap(LearnerMode.init(rawValue:)) ?? derivedDefault
357	
358	        let savedScan = UserDefaults.standard.string(forKey: Keys.photoScanLanguage)
359	        self.photoScanLanguage = savedScan.flatMap(PhotoScanLanguage.init(rawValue:)) ?? .auto
360	
361	        // Default ON: dual narration is purely additive and useful for both audiences.
362	        self.dualNarration = UserDefaults.standard.object(forKey: Keys.dualNarration) as? Bool ?? true
363	
364	        // Speech rate: default matches AVSpeechUtteranceDefaultSpeechRate (0.5),
365	        // clamped in case a stale/out-of-range value was persisted.
366	        let savedRate = UserDefaults.standard.object(forKey: Keys.ttsRate) as? Double ?? 0.5
367	        self.ttsRate = min(max(savedRate, Self.ttsRateRange.lowerBound), Self.ttsRateRange.upperBound)
368	
369	        self.aiAudioEnabled = UserDefaults.standard.object(forKey: Keys.aiAudioEnabled) as? Bool ?? false
370	
371	        let savedRegion = UserDefaults.standard.string(forKey: Keys.aiAudioRegion)
372	        self.aiAudioRegion = savedRegion.flatMap(MiniMaxAPIRegion.init(rawValue:)) ?? .mainlandChina
373	
374	        let savedModel = UserDefaults.standard.string(forKey: Keys.aiAudioModel)?
375	            .trimmingCharacters(in: .whitespacesAndNewlines)
376	        self.aiAudioModel = savedModel.flatMap { $0.isEmpty ? nil : $0 }
377	            ?? MiniMaxSpeechConfiguration.defaultModel
378	
379	        let savedChineseVoice = UserDefaults.standard.string(forKey: Keys.aiAudioChineseVoice)?
380	            .trimmingCharacters(in: .whitespacesAndNewlines)
381	        self.aiAudioChineseVoice = savedChineseVoice.flatMap { $0.isEmpty ? nil : $0 }
382	            ?? MiniMaxSpeechConfiguration.defaultChineseVoice
383	
384	        let savedEnglishVoice = UserDefaults.standard.string(forKey: Keys.aiAudioEnglishVoice)?
385	            .trimmingCharacters(in: .whitespacesAndNewlines)
386	        self.aiAudioEnglishVoice = savedEnglishVoice.flatMap { $0.isEmpty ? nil : $0 }
387	            ?? MiniMaxSpeechConfiguration.defaultEnglishVoice
388	
389	        self.aiAudioChineseVoiceUsesCustomLanguage = UserDefaults.standard.object(
390	            forKey: Keys.aiAudioChineseVoiceUsesCustomLanguage
391	        ) as? Bool ?? false
392	        self.aiAudioEnglishVoiceUsesCustomLanguage = UserDefaults.standard.object(
393	            forKey: Keys.aiAudioEnglishVoiceUsesCustomLanguage
394	        ) as? Bool ?? false
395	
396	        let savedAISpeed = UserDefaults.standard.object(forKey: Keys.aiAudioSpeed) as? Double ?? 1.0
397	        self.aiAudioSpeed = min(max(savedAISpeed, Self.aiAudioSpeedRange.lowerBound),
398	                                Self.aiAudioSpeedRange.upperBound)
399	
400	        self.aiAudioFallbackToSystemSpeech =
401	            UserDefaults.standard.object(forKey: Keys.aiAudioFallbackToSystemSpeech) as? Bool ?? true
402	    }
403	}
