//
//  LearningContext.swift
//  SwiftMandarin
//
//  One place to answer the questions every bilingual surface keeps asking:
//  which side of an English/Chinese pair is the learner studying, which side
//  do they already read, how should each side be spoken, and which learner
//  aids (pinyin, tones) are meaningful at all.
//
//  Why this exists
//  ---------------
//  The app is a mirror: an English speaker learning Mandarin and a Mandarin
//  speaker learning English get the same features with the two languages
//  swapped. Before this type, that swap was re-derived inline at every call
//  site from `LocalizationManager.shared.learningIsChinese`, which made it
//  easy to reverse the *text* while forgetting the *voice*, the *prompt
//  language*, or the *pinyin affordance* that goes with it. Deriving them all
//  from one value keeps the two directions genuinely symmetric.
//
//  The core is a pure, `Sendable`, Foundation-only value so the mirror
//  property ("every accessor of the reverse context equals the swapped
//  accessor of the forward context") can be asserted by the standalone
//  contract runner in `scripts/learning-direction-checks/` without a UI, a
//  bundle, or a main actor.
//

import Foundation

// MARK: - Learning Context (pure)

/// The resolved language roles for one learner. `learningIsChinese` is the
/// only stored fact; everything else is that fact projected onto a specific
/// question a view or service needs answered.
nonisolated struct LearningContext: Equatable, Sendable {

    /// Whether Mandarin is the language being *studied*. When false the user
    /// is a Mandarin speaker studying English and every pair is reversed.
    let learningIsChinese: Bool

    init(learningIsChinese: Bool) {
        self.learningIsChinese = learningIsChinese
    }

    /// The user's native language is always the other one.
    var nativeIsChinese: Bool { !learningIsChinese }

    /// The same learner with the two languages swapped. Used by the contract
    /// checks to assert the two directions really are mirror images.
    var mirrored: LearningContext {
        LearningContext(learningIsChinese: !learningIsChinese)
    }

    // MARK: Text selection

    /// The side shown big — the language being studied.
    func primary(chinese: String, english: String) -> String {
        learningIsChinese ? chinese : english
    }

    /// The side shown small — the language the user already reads.
    func secondary(chinese: String, english: String) -> String {
        learningIsChinese ? english : chinese
    }

    // MARK: Speech

    /// BCP-47 code for reading the studied side aloud.
    var learningSpeechCode: String { learningIsChinese ? "zh-CN" : "en-US" }

    /// BCP-47 code for reading the native-language gloss aloud.
    var nativeSpeechCode: String { learningIsChinese ? "en-US" : "zh-CN" }

    /// Speech code for one side of a pair, chosen by which language it is in
    /// rather than by the learner — a Chinese string is always spoken by a
    /// Mandarin voice, whichever direction the learner is going.
    func speechCode(isChinese: Bool) -> String {
        isChinese ? "zh-CN" : "en-US"
    }

    // MARK: Learner aids

    /// Pinyin, tone marks, tone colors, and tone drills teach the *reading* of
    /// Chinese. They are learner scaffolding, so they belong only to the
    /// learner who is decoding Chinese — a native Mandarin reader studying
    /// English needs none of them on their own language.
    var showsPinyinAffordances: Bool { learningIsChinese }

    /// Whether the tappable word-by-word reader should segment Chinese
    /// (`RubyTextView`) rather than English (`EnglishRubyTextView`).
    var interactiveReaderIsChinese: Bool { learningIsChinese }

    // MARK: Prompt-facing language names

    /// English-language names used inside AI prompts (never shown in the UI),
    /// so a model is told plainly which language to teach and which to
    /// explain in. Kept here so the explanation, translation, conversation,
    /// and story prompts cannot drift apart.
    var learningLanguagePromptName: String {
        learningIsChinese ? "Mandarin Chinese (Simplified, 简体中文)" : "English"
    }

    var nativeLanguagePromptName: String {
        learningIsChinese ? "English" : "Simplified Chinese (简体中文)"
    }
}

// MARK: - Live resolution

extension LearningContext {

    /// The context implied by the current interface language. The interface
    /// language *is* the user's native language (see `LocalizationManager`),
    /// so one read answers the whole question.
    @MainActor
    static var current: LearningContext {
        LearningContext(learningIsChinese: LocalizationManager.shared.learningIsChinese)
    }
}

// MARK: - UI-facing helpers

@MainActor
extension LearningContext {

    /// Localized name of the language being studied, for section headers and
    /// button labels ("Read the English aloud" / "朗读英文").
    var learningLanguageDisplayName: String {
        learningIsChinese ? String(localized: "Chinese") : String(localized: "English")
    }

    /// Localized name of the language the user already reads.
    var nativeLanguageDisplayName: String {
        learningIsChinese ? String(localized: "English") : String(localized: "Chinese")
    }

    /// Speak the studied side with the voice that matches it.
    func speakLearning(_ text: String) {
        SpeechService.speak(text, languageCode: learningSpeechCode)
    }

    /// Speak the native-language gloss with the voice that matches it.
    func speakNative(_ text: String) {
        SpeechService.speak(text, languageCode: nativeSpeechCode)
    }

    /// Read a pair aloud in the order that serves this learner: the studied
    /// language always leads, and the gloss follows only when the user asked
    /// for dual narration. Returns immediately; narration continues in the
    /// background so callers stay usable from a button action.
    func speakPair(chinese: String, english: String) {
        let lead = primary(chinese: chinese, english: english)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let follow = secondary(chinese: chinese, english: english)
            .trimmingCharacters(in: .whitespacesAndNewlines)

        guard AppPreferences.shared.dualNarration, !follow.isEmpty, !lead.isEmpty else {
            speakLearning(lead.isEmpty ? follow : lead)
            return
        }

        Task { @MainActor in
            try? await SpeechService.speakAndWait(lead, languageCode: learningSpeechCode)
            try? await SpeechService.speakAndWait(follow, languageCode: nativeSpeechCode)
        }
    }
}

