        var seen = Set<String>()
        var targets: [BatchAudioTarget] = []

        func append(
            text rawText: String,
            languageCode: String,
            configuration: MiniMaxSpeechConfiguration,
            term: BatchAudioTermSnapshot
        ) {
            let text = rawText.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !text.isEmpty else { return }
            let identity = MiniMaxSpeechCacheIdentity(
                text: text,
                languageCode: languageCode,
                configuration: configuration
            )
            guard seen.insert(identity.cacheKey).inserted else { return }
            targets.append(
                BatchAudioTarget(
                    termID: term.termID,
                    displayWord: term.displayWord,
                    text: text,
                    languageCode: identity.languageCode,
                    identity: identity
                )
            )
        }

        for term in terms {
            switch scope {
            case .learningLanguage:
                if learningIsChinese {
                    append(
                        text: term.chineseText,
                        languageCode: "zh-CN",
                        configuration: chineseConfiguration,
                        term: term
                    )
                } else {
                    append(
                        text: term.englishText,
                        languageCode: "en-US",
                        configuration: englishConfiguration,
                        term: term
                    )
                }
            case .bothLanguages:
                // Queue the studied language first so the clips the learner
                // actually practises with are ready earliest, and so a run
                // stopped part-way still leaves a usable library. Which one
                // that is mirrors the learner mode.
                let chinese = {
                    append(
                        text: term.chineseText,
                        languageCode: "zh-CN",
                        configuration: chineseConfiguration,
                        term: term
                    )
                }
                let english = {
                    append(
                        text: term.englishText,
                        languageCode: "en-US",
                        configuration: englishConfiguration,
                        term: term
                    )
                }
                if learningIsChinese {
                    chinese()
                    english()
                } else {
                    english()
                    chinese()
                }
            }
        }

        let targetIDs = Set(targets.map(\.id))
        let cached = existingRecordIDs.intersection(targetIDs)
        return BatchAudioPlan(
            scope: scope,
            allTargets: targets,
            pendingTargets: targets.filter { !cached.contains($0.id) },
            cachedRecordIDs: cached
        )
    }
}

