/// the user's Appearance settings (show/hide, above/below/inline, tone colors).
struct RubyWordView: View {
    let segment: RubySegment
    let action: () -> Void

    @State private var isHovered: Bool = false

    @AppStorage("showPinyin") private var showPinyin: Bool = true
    @AppStorage("pinyinPosition") private var pinyinPosition: String = "above"
    @AppStorage("toneColors") private var toneColors: Bool = true

    var body: some View {
        Button(action: action) {
            wordLayout
                .padding(.horizontal, 6)
                .padding(.vertical, 4)
                .background(
                    RoundedRectangle(cornerRadius: 6)
                        .fill(isHovered ? Color.accentColor.opacity(0.1) : Color.clear)
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 6)
                        .stroke(segment.partOfSpeech.color.opacity(0.3), lineWidth: 1)
                )
        }
        .buttonStyle(.plain)
        .onHover { hovering in
            withAnimation(.easeInOut(duration: 0.15)) {
                isHovered = hovering
            }
        }
    }

    @ViewBuilder
    private var wordLayout: some View {
        if !showPinyin {
            characterText
        } else {
            switch pinyinPosition {
            case "below":
                VStack(spacing: 2) {
                    characterText
                    pinyinText
                }
            case "inline":
                HStack(alignment: .firstTextBaseline, spacing: 4) {
                    characterText
                    pinyinText
                }
            default:  // "above"
                VStack(spacing: 2) {
                    pinyinText
                    characterText
                }
            }
        }
    }

    /// Pinyin line. With tone colors enabled, each SYLLABLE gets its own tone
    /// color from the shared `PinyinConverter.Tone` palette — a multi-syllable

