#!/usr/bin/env python3
"""Read/write Localizable.xcstrings in Xcode's exact serialization style.

Xcode writes `"key" : value` (a space either side of the colon), 2-space
indent, and an empty object as `{\\n\\n<indent>}`. Round-tripping through plain
`json.dumps` would reformat all 315 KB of the file and bury a two-line change
in a whole-file diff, so this emitter reproduces Xcode's style byte for byte
instead. `selftest` proves that on the live file.

Key ORDER is preserved as read rather than re-sorted: Xcode's collation is not
Python's (it files ".%@" before "%@ (%@)", i.e. not by code point), and since
Python dicts keep document order, preserving it sidesteps the question. Any
genuinely new key lands at the end; Xcode refiles it on the next build.
"""
import json
import sys
from pathlib import Path

CATALOG = Path("/Users/rogerlin/Downloads/SwiftMandarin-main/SwiftMandarin/Localizable.xcstrings")


def emit(value, indent=0):
    pad = "  " * indent
    inner = "  " * (indent + 1)
    if isinstance(value, dict):
        if not value:
            return "{\n\n" + pad + "}"
        parts = [
            f"{inner}{json.dumps(k, ensure_ascii=False)} : {emit(v, indent + 1)}"
            for k, v in value.items()
        ]
        return "{\n" + ",\n".join(parts) + "\n" + pad + "}"
    if isinstance(value, list):
        if not value:
            return "[\n\n" + pad + "]"
        parts = [f"{inner}{emit(v, indent + 1)}" for v in value]
        return "[\n" + ",\n".join(parts) + "\n" + pad + "]"
    return json.dumps(value, ensure_ascii=False)


def dumps(catalog):
    return emit(catalog) + "\n"


def load():
    return json.loads(CATALOG.read_text())


def save(catalog):
    CATALOG.write_text(dumps(catalog))


def selftest():
    original = CATALOG.read_text()
    rendered = dumps(json.loads(original))
    if rendered == original:
        print("round-trip byte-identical")
        return 0
    # Show the first divergence so a format drift is diagnosable.
    for i, (a, b) in enumerate(zip(original, rendered)):
        if a != b:
            print(f"diverges at byte {i}")
            print("orig:", repr(original[max(0, i - 60):i + 60]))
            print("new :", repr(rendered[max(0, i - 60):i + 60]))
            break
    else:
        print(f"length differs: {len(original)} vs {len(rendered)}")
    return 1


if __name__ == "__main__":
    raise SystemExit(selftest() if sys.argv[1:2] == ["selftest"] else 0)

