        var resolvedPartOfSpeech = partOfSpeech.trimmingCharacters(in: .whitespacesAndNewlines)
        if resolvedPartOfSpeech.isEmpty && saveAsPhrase {
            resolvedPartOfSpeech = "phrase"
        }

