2	//  StudyHubView.swift
3	//  SwiftMandarin
4	//
5	//  The Study tab (iOS): one hub for every learning surface — flashcard
6	//  review, practice drills, AI conversation, the reader, and the library
7	//  (vocabulary, phrases, history, stats). On macOS these destinations are
8	//  sidebar items instead, so this hub is iOS-only in practice, but it
9	//  compiles everywhere for safety.
10	//
11	
