14	/// Push destinations inside the Study hub. Raw values match the strings used
15	/// by `AppRouteStore.openStudy(route:)` so Home deep-links resolve here.
16	enum StudyRoute: String, Hashable {
17	    case learn
18	    case practice
19	    case conversation
20	    case reader
21	    case vocabulary
22	    case phrases
23	    case history
24	    case stats
25	}
26	
27	struct StudyHubView: View {
28	    @Binding var selectedTab: AppTab
29	    @Environment(AppRouteStore.self) private var routeStore
30	    @Environment(SavedTermsStore.self) private var savedTermsStore
31	    @Environment(LearningProgressStore.self) private var progressStore
