42	                }
43	                .padding()
44	            }
45	            .background(SMTheme.pageBackground)
46	            .navigationTitle("Study")
47	            .navigationDestination(for: StudyRoute.self) { route in
48	                switch route {
49	                case .learn: LearnView()
50	                case .practice: PracticeHubView()
51	                case .conversation: ConversationView()
52	                case .reader: ReaderView()
53	                case .vocabulary: VocabularyView()
54	                case .phrases: PhrasesView()
