56	                case .stats: StatsView()
57	                }
58	            }
59	        }
60	        // A Siri/Home "start review" action, or a Home deep-link into a
61	        // specific library screen, routes to this tab on iOS; push the matching
62	        // destination so the pending action is consumed exactly as it would be
63	        // if these were top-level tabs.
64	        .onChange(of: routeStore.pendingAction?.id, initial: true) { _, _ in
65	            switch routeStore.pendingAction?.kind {
66	            case .startReview:
67	                if path.last != .learn { path.append(.learn) }
